module Main_Decoder ( Op, RegWrite, ImmSrc, ALUSrc, MemWrite, ResultSrc, 
        Branch, ALUOp, Jump );
  input [6:0] Op;
  output [1:0] ImmSrc;
  output [1:0] ResultSrc;
  output [1:0] ALUOp;
  output RegWrite, ALUSrc, MemWrite, Branch, Jump;
  wire   Branch, n4, n5, n6, n7, n8, n9, \ResultSrc[1] , n2, n3;
  assign ALUOp[0] = Branch;
  assign Jump = \ResultSrc[1] ;
  assign ResultSrc[1] = \ResultSrc[1] ;

  NOR3BX2M U3 ( .AN(n7), .B(Op[2]), .C(Op[3]), .Y(Branch) );
  INVX2M U4 ( .A(MemWrite), .Y(n2) );
  NAND2X2M U5 ( .A(n2), .B(n5), .Y(ImmSrc[0]) );
  NAND3BX2M U6 ( .AN(ALUOp[1]), .B(n5), .C(n6), .Y(RegWrite) );
  NAND2X2M U7 ( .A(n6), .B(n2), .Y(ALUSrc) );
  OR2X2M U8 ( .A(Branch), .B(\ResultSrc[1] ), .Y(ImmSrc[1]) );
  INVX2M U9 ( .A(n5), .Y(\ResultSrc[1] ) );
  NOR3BX2M U10 ( .AN(Op[4]), .B(n4), .C(n3), .Y(ALUOp[1]) );
  NAND4BX1M U11 ( .AN(Op[2]), .B(Op[1]), .C(Op[0]), .D(n8), .Y(n4) );
  NOR2X2M U12 ( .A(Op[6]), .B(Op[3]), .Y(n8) );
  NOR3X2M U13 ( .A(n3), .B(Op[4]), .C(n4), .Y(MemWrite) );
  AND4X2M U14 ( .A(Op[6]), .B(Op[5]), .C(n9), .D(Op[1]), .Y(n7) );
  NOR2BX2M U15 ( .AN(Op[0]), .B(Op[4]), .Y(n9) );
  INVX2M U16 ( .A(Op[5]), .Y(n3) );
  NOR3X2M U17 ( .A(n4), .B(Op[5]), .C(Op[4]), .Y(ResultSrc[0]) );
  OR2X2M U18 ( .A(n4), .B(Op[5]), .Y(n6) );
  NAND3X2M U19 ( .A(Op[2]), .B(n7), .C(Op[3]), .Y(n5) );
endmodule


module ALU_Decoder ( ALUOp, funct3, funct7, op, ALUControl );
  input [1:0] ALUOp;
  input [2:0] funct3;
  input [6:0] funct7;
  input [6:0] op;
  output [2:0] ALUControl;
  wire   n3, n4, n5, n6, n7, n2;

  AND2X2M U3 ( .A(ALUOp[1]), .B(n2), .Y(n7) );
  INVX2M U4 ( .A(ALUOp[0]), .Y(n2) );
  INVX2M U5 ( .A(n4), .Y(ALUControl[1]) );
  NOR4X1M U6 ( .A(n3), .B(ALUOp[0]), .C(funct3[2]), .D(funct3[0]), .Y(
        ALUControl[2]) );
  NAND2X2M U7 ( .A(funct3[1]), .B(ALUOp[1]), .Y(n3) );
  OAI221X1M U8 ( .A0(funct3[0]), .A1(n4), .B0(ALUOp[1]), .B1(n2), .C0(n5), .Y(
        ALUControl[0]) );
  AOI32X1M U9 ( .A0(op[5]), .A1(funct7[5]), .A2(n6), .B0(n6), .B1(funct3[1]), 
        .Y(n5) );
  NOR3BX2M U10 ( .AN(n7), .B(funct3[0]), .C(funct3[2]), .Y(n6) );
  NAND3X2M U11 ( .A(n7), .B(funct3[1]), .C(funct3[2]), .Y(n4) );
endmodule


module Control_Unit_Top ( Op, RegWrite, ImmSrc, ALUSrc, MemWrite, ResultSrc, 
        Branch, funct3, funct7, ALUControl, Jump );
  input [6:0] Op;
  output [1:0] ImmSrc;
  output [1:0] ResultSrc;
  input [2:0] funct3;
  input [6:0] funct7;
  output [2:0] ALUControl;
  output RegWrite, ALUSrc, MemWrite, Branch, Jump;

  wire   [1:0] ALUOp;

  Main_Decoder md ( .Op(Op), .RegWrite(RegWrite), .ImmSrc(ImmSrc), .ALUSrc(
        ALUSrc), .MemWrite(MemWrite), .ResultSrc(ResultSrc), .Branch(Branch), 
        .ALUOp(ALUOp), .Jump(Jump) );
  ALU_Decoder ad ( .ALUOp(ALUOp), .funct3(funct3), .funct7(funct7), .op(Op), 
        .ALUControl(ALUControl) );
endmodule


